"""Shared, route-based communication accounting.

All values are binary megabytes (MiB, retained as ``*_MB`` for compatibility
with the existing result schema).  Only tensors that cross a simulated node
boundary belong here; local copies and validation forwards do not.
"""

from collections.abc import Mapping

import torch


COMMUNICATION_ROUTES = (
    "client_to_server_MB",
    "server_to_client_MB",
    "client_to_edge_MB",
    "edge_to_client_MB",
    "edge_to_cloud_MB",
    "cloud_to_edge_MB",
)


def new_communication_tracker():
    """Return a tracker with the identical schema used by every method."""
    return {route: 0.0 for route in COMMUNICATION_ROUTES} | {"total_comm_MB": 0.0}


def bytes_of(payload):
    """Exact tensor-storage bytes in a tensor or nested tensor container."""
    if payload is None:
        return 0
    if isinstance(payload, torch.Tensor):
        return payload.numel() * payload.element_size()
    if isinstance(payload, Mapping):
        return sum(bytes_of(value) for value in payload.values())
    if isinstance(payload, (tuple, list)):
        return sum(bytes_of(value) for value in payload)
    return 0


def mb_of(payload):
    return bytes_of(payload) / (1024**2)


def add_communication(tracker, route, *, payload=None, mb=None, copies=1):
    """Add one transmitted payload and keep the compatibility total current."""
    if route not in COMMUNICATION_ROUTES:
        raise KeyError(f"unknown communication route: {route}")
    if (payload is None) == (mb is None):
        raise ValueError("provide exactly one of payload or mb")
    amount = (mb_of(payload) if mb is None else float(mb)) * int(copies)
    tracker[route] += amount
    tracker["total_comm_MB"] += amount
    return amount


def assert_communication_total(tracker):
    """Raise if a tracker total is inconsistent; useful at report boundaries."""
    expected = sum(tracker[route] for route in COMMUNICATION_ROUTES)
    if abs(tracker["total_comm_MB"] - expected) > 1e-9:
        raise AssertionError(
            f"communication total {tracker['total_comm_MB']} != route sum {expected}"
        )
    return expected

"""Phase-0 reproducibility, identity, and overwrite guards."""

from __future__ import annotations

import hashlib
import inspect
import json
import os
import subprocess
from collections import Counter
from pathlib import Path
from typing import Any, Dict, Iterable, Mapping, Sequence

import torch


def _jsonable(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {str(k): _jsonable(v) for k, v in sorted(value.items(), key=lambda x: str(x[0]))}
    if isinstance(value, (list, tuple)):
        return [_jsonable(v) for v in value]
    if isinstance(value, set):
        return sorted(_jsonable(v) for v in value)
    if hasattr(value, "item"):
        try:
            return value.item()
        except (ValueError, TypeError):
            pass
    return value


def canonical_config(config: Mapping[str, Any]) -> str:
    """Return stable, unrounded JSON for a fully resolved configuration."""
    return json.dumps(_jsonable(config), sort_keys=True, separators=(",", ":"), allow_nan=False)


def resolved_config_hash(config: Mapping[str, Any], effective_ehsfp: Mapping[str, Any]) -> str:
    payload = {"config": dict(config), "effective_ehsfp": dict(effective_ehsfp)}
    return hashlib.sha256(canonical_config(payload).encode()).hexdigest()


def partition_hash(user_groups: Mapping[Any, Iterable[Any]]) -> str:
    normalized = {str(k): sorted(int(i) for i in v) for k, v in user_groups.items()}
    return hashlib.sha256(canonical_config(normalized).encode()).hexdigest()


def index_batch_hash(indices: Iterable[Any]) -> str:
    """Hash an ordered sampler/client-selection batch."""
    normalized = [int(index) for index in indices]
    return hashlib.sha256(canonical_config(normalized).encode()).hexdigest()


def state_dict_hash(state_dict: Mapping[str, torch.Tensor]) -> str:
    """Hash tensor names, metadata, and exact CPU bytes in a model state."""
    digest = hashlib.sha256()
    for name, tensor in sorted(state_dict.items()):
        value = tensor.detach().cpu().contiguous()
        digest.update(name.encode())
        digest.update(str(value.dtype).encode())
        digest.update(canonical_config(list(value.shape)).encode())
        digest.update(value.reshape(-1).view(torch.uint8).numpy().tobytes())
    return digest.hexdigest()


def write_run_fingerprints(path: str, fingerprints: Mapping[str, Any]) -> None:
    """Atomically persist the small reproducibility record for a run."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    temporary = f"{path}.tmp"
    with open(temporary, "w", encoding="utf-8") as handle:
        json.dump(_jsonable(fingerprints), handle, indent=2, sort_keys=True)
        handle.write("\n")
    os.replace(temporary, path)


def git_commit(root: str) -> str:
    return subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=root, text=True).strip()


def architecture_manifest(models: Sequence[Any]) -> Dict[str, Any]:
    tiers = []
    for model in models:
        cls = type(model)
        try:
            source = inspect.getsourcefile(cls) or "unknown"
            source_digest = hashlib.sha256(Path(source).read_bytes()).hexdigest()
        except (OSError, TypeError):
            source, source_digest = "unknown", "unknown"
        tiers.append({
            "class": f"{cls.__module__}.{cls.__qualname__}",
            "source": os.path.abspath(source) if source != "unknown" else source,
            "source_sha256": source_digest,
            "state_shapes": {k: list(v.shape) for k, v in model.state_dict().items()},
            "parameters": sum(p.numel() for p in model.parameters()),
            "trainable_parameters": sum(p.numel() for p in model.parameters() if p.requires_grad),
        })
    digest = hashlib.sha256(canonical_config(tiers).encode()).hexdigest()
    return {"architecture_hash": digest, "architecture_id": digest[:12], "tiers": tiers}


def prepare_run_dir(base_dir: str, architecture_id: str, config_hash: str) -> str:
    """Reserve an architecture/config-specific directory without overwriting."""
    run_dir = os.path.join(base_dir, architecture_id, config_hash)
    if os.path.exists(run_dir):
        raise FileExistsError(
            f"Refusing to overwrite existing run directory {run_dir}; "
            "use a distinct resolved config or archive the existing run."
        )
    os.makedirs(run_dir, exist_ok=False)
    return run_dir


def validate_checkpoint_config_hash(checkpoint: Mapping[str, Any], expected_hash: str) -> None:
    found = checkpoint.get("resolved_config_hash")
    if found != expected_hash:
        raise RuntimeError(
            f"Checkpoint config hash mismatch: expected {expected_hash}, found {found!r}"
        )


class RuntimeCounters:
    """Small serializable counter set shared by all E-HSFP components."""

    _DEFAULTS = (
        "memory.reads", "memory.writes", "memory.replays",
        "memory.replay_calls", "memory.changed_classes",
        "reliability.aggregation_calls", "reliability.nonuniform_weight_calls",
        "reliability.weight_variance_sum", "reliability.weight_variance_observations",
        "prc.calls", "prc.shared_classes", "prc.nonzero_loss_calls",
        "prc.loss_sum", "prc.loss_observations",
        "dropout.apply_calls", "dropout.changed_calls", "dropout.total_seen",
        "dropout.active_set_total", "dropout.active_set_observations",
        "dropout.active_set_last",
    )

    def __init__(self) -> None:
        self._counts: Counter[str] = Counter({key: 0 for key in self._DEFAULTS})

    def increment(self, key: str, amount=1) -> None:
        self._counts[key] += amount

    def set(self, key: str, value) -> None:
        self._counts[key] = value

    def snapshot(self) -> Dict[str, Any]:
        # Device counters are deliberately accumulated without .item() in hot
        # CUDA loops.  Materialize them together at this explicit reporting
        # boundary instead of forcing one host/device synchronization per loss
        # or per class.
        result = {
            key: value.item() if hasattr(value, "item") else value
            for key, value in self._counts.items()
        }
        rel_n = result["reliability.weight_variance_observations"]
        prc_n = result["prc.loss_observations"]
        active_n = result["dropout.active_set_observations"]
        result["reliability.weight_variance"] = (
            result["reliability.weight_variance_sum"] / rel_n if rel_n else 0.0
        )
        result["prc.loss_mean"] = result["prc.loss_sum"] / prc_n if prc_n else 0.0
        result["dropout.active_set_mean"] = (
            result["dropout.active_set_total"] / active_n if active_n else 0.0
        )
        return dict(sorted(result.items()))

"""
E-HSFP Metrics Logger.

Collects all E-HSFP-specific metrics into a structured dict,
compatible with wandb.log() and JSON output.
"""

import json
import os
from typing import Dict, Any, Optional

try:
    import wandb
except ImportError:
    wandb = None


class EHSFPMetricsLogger:
    """Collects E-HSFP metrics per epoch and supports wandb + JSON output."""

    def __init__(self):
        self.history: list = []
        self._current: Dict[str, Any] = {}

    def reset_epoch(self) -> None:
        """Start collecting metrics for a new epoch."""
        if self._current:
            self.history.append(self._current)
        self._current = {}

    def log(self, key: str, value: Any) -> None:
        self._current[key] = value

    def log_dict(self, d: Dict[str, Any]) -> None:
        self._current.update(d)

    def log_memory_stats(
        self,
        num_current: int,
        num_memory: int,
        replay_ratio: float,
        avg_age: float,
        avg_reliability: float,
    ) -> None:
        self.log("ehsfp/num_current_prototypes", num_current)
        self.log("ehsfp/num_memory_prototypes", num_memory)
        self.log("ehsfp/memory_replay_ratio", replay_ratio)
        self.log("ehsfp/avg_prototype_age", avg_age)
        self.log("ehsfp/avg_reliability_weight", avg_reliability)

    def log_losses(
        self,
        task_loss: Optional[float] = None,
        prc_loss: Optional[float] = None,
        dropout_loss: Optional[float] = None,
        contrastive_loss: Optional[float] = None,
    ) -> None:
        if task_loss is not None:
            self.log("ehsfp/task_loss", task_loss)
        if prc_loss is not None:
            self.log("ehsfp/prc_loss", prc_loss)
        if dropout_loss is not None:
            self.log("ehsfp/dropout_consistency_loss", dropout_loss)
        if contrastive_loss is not None:
            self.log("ehsfp/contrastive_loss", contrastive_loss)

    def log_dropout_stats(
        self,
        dropout_rate: float,
        dropped_count: int,
    ) -> None:
        self.log("ehsfp/prototype_dropout_rate", dropout_rate)
        self.log("ehsfp/dropped_prototype_count", dropped_count)

    def log_communication(
        self,
        prototype_payload_MB: float,
        total_comm_MB: float,
    ) -> None:
        self.log("ehsfp/prototype_payload_MB", prototype_payload_MB)
        self.log("ehsfp/total_comm_MB", total_comm_MB)

    def flush_to_wandb(self, extra: Optional[Dict] = None) -> None:
        """Send current epoch metrics to wandb."""
        if wandb is not None and wandb.run is not None:
            data = dict(self._current)
            if extra:
                data.update(extra)
            wandb.log(data)

    def get_current(self) -> Dict[str, Any]:
        return dict(self._current)

    def append_jsonl(self, path: str, extra: Optional[Dict] = None) -> None:
        """Persist an epoch record without display rounding.

        Diagnostic metrics can occasionally be NaN/Inf (e.g. a degenerate
        per-class reliability variance); sanitize to null so a single non-finite
        diagnostic never aborts the whole run's logging (and final test/metrics
        write). This keeps runs robust without hiding real training divergence,
        which is already tracked via the finite loss/accuracy fields.
        """
        import math

        def _sanitize(o):
            if isinstance(o, float):
                return o if math.isfinite(o) else None
            if isinstance(o, dict):
                return {k: _sanitize(v) for k, v in o.items()}
            if isinstance(o, (list, tuple)):
                return [_sanitize(v) for v in o]
            return o

        data = _sanitize(dict(self._current))
        if extra:
            data.update(_sanitize(dict(extra)))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "a") as handle:
            handle.write(json.dumps(data, sort_keys=True, allow_nan=False) + "\n")

    def finalize(self) -> list:
        """Flush remaining metrics and return full history."""
        if self._current:
            self.history.append(self._current)
            self._current = {}
        return self.history

"""Prototype-space ablations shared by H-SFP tiers."""

from typing import Dict, Mapping, Optional

import torch
from torch import nn
from torch.nn import functional as F


PROTOTYPE_SPACES = ("raw", "centered_cosine", "whitened_cosine")

# Prototype spaces that use the angular (cosine) cloud head + a centered frame.
COSINE_SPACES = ("centered_cosine", "whitened_cosine")


def validate_prototype_space(value: Optional[str]) -> str:
    """Resolve the opt-in prototype space without changing legacy configs."""
    value = "raw" if value is None else str(value)
    if value not in PROTOTYPE_SPACES:
        raise ValueError(
            f"prototype_space must be one of {PROTOTYPE_SPACES}, got {value!r}"
        )
    return value


@torch.no_grad()
def derive_whitening_transform(
    input_outputs: Mapping,
    mean: torch.Tensor,
    support_map: Optional[Mapping] = None,
    shrinkage: float = 0.1,
    eps: float = 1e-3,
    device: Optional[torch.device] = None,
) -> torch.Tensor:
    """Derive a symmetric ZCA whitening matrix from the BETWEEN-class scatter.

    The class prototype means are already transmitted; their covariance around
    the global ``mean`` (weighted by existing support counts) captures the
    dominant, near-collinear directions that collapse raw prototypes. ZCA
    whitening ``W = V diag((lambda+eps)^-1/2) V^T`` decorrelates and equalizes
    those directions. Shrinkage toward the identity keeps small/degenerate
    eigenvalues from exploding. No feature tensor is added to the payload: this
    is computed at the reconstructing tier from already-received class means.
    """
    target_device = torch.device(device) if device is not None else mean.device
    mu = mean.detach().to(target_device).reshape(-1)
    dim = mu.numel()
    scatter = torch.zeros(dim, dim, device=target_device, dtype=torch.float32)
    total = 0.0
    for source_id, outputs in input_outputs.items():
        if outputs is None:
            continue
        prototypes, _ = outputs
        for class_id, prototype in prototypes.items():
            count = 1
            if support_map is not None:
                count = int(support_map.get(source_id, {}).get(class_id, 0)) or 1
            centered = prototype.detach().to(target_device).reshape(-1).float() - mu.float()
            scatter = scatter + count * torch.outer(centered, centered)
            total += count
    if total <= 0:
        return torch.eye(dim, device=target_device, dtype=torch.float32)
    cov = scatter / total
    # Shrink toward a scaled identity for numerical stability.
    trace_mean = torch.trace(cov) / dim
    cov = (1.0 - shrinkage) * cov + shrinkage * trace_mean * torch.eye(
        dim, device=target_device, dtype=torch.float32
    )
    evals, evecs = torch.linalg.eigh(cov)
    inv_sqrt = torch.rsqrt(torch.clamp(evals, min=eps))
    whitener = (evecs * inv_sqrt.unsqueeze(0)) @ evecs.t()
    return whitener.detach()


def whiten_features(
    features: torch.Tensor,
    mean: Optional[torch.Tensor],
    whitener: Optional[torch.Tensor],
) -> torch.Tensor:
    """Center then whiten batched real/synthetic features: ``(x - mu) W``.

    Preserves the original per-sample feature shape (e.g. ``[B, C, 1, 1]``) by
    flattening to ``[B, D]`` for the matmul and reshaping back.
    """
    out = center_features(features, mean)
    if whitener is None:
        return out
    orig_shape = out.shape
    flat = out.reshape(orig_shape[0], -1)
    w = whitener.to(device=flat.device, dtype=flat.dtype)
    return (flat @ w).reshape(orig_shape)


@torch.no_grad()
def whiten_source_outputs(
    input_outputs: Mapping,
    mean: torch.Tensor,
    whitener: torch.Tensor,
) -> Dict:
    """Express prototypes in the centered+whitened space.

    Class means are centered and whitened. Diagonal stds are transformed to the
    diagonal of ``W diag(std^2) W^T`` so the per-class Gaussian remains a valid
    (diagonal-approximated) sampler in the whitened frame.
    """
    whitened = {}
    for source_id, outputs in input_outputs.items():
        if outputs is None:
            whitened[source_id] = None
            continue
        prototypes, stds = outputs
        w = whitener.to(device=next(iter(prototypes.values())).device, dtype=torch.float32)
        mu = mean.to(w.device, torch.float32).reshape(-1)
        new_protos = {}
        for class_id, prototype in prototypes.items():
            orig_shape = prototype.shape
            centered = prototype.detach().to(w.device).float().reshape(-1) - mu
            new_protos[class_id] = (centered @ w).reshape(orig_shape).to(prototype.dtype)
        new_stds = stds
        if isinstance(stds, Mapping):
            new_stds = {}
            for class_id, std in stds.items():
                orig_shape = std.shape
                var = (std.detach().to(w.device).float().reshape(-1) ** 2)
                # diag(W diag(var) W^T) = sum_j W_ij^2 var_j  (per output dim i)
                new_var = (w.pow(2) @ var).clamp_min(0.0)
                new_stds[class_id] = new_var.sqrt().reshape(orig_shape).to(std.dtype)
        whitened[source_id] = (new_protos, new_stds)
    return whitened


@torch.no_grad()
def derive_global_feature_mean(
    input_outputs: Mapping,
    support_map: Optional[Mapping] = None,
    device: Optional[torch.device] = None,
) -> torch.Tensor:
    """Derive the sample-weighted global mean from existing prototype stats.

    Each transmitted class prototype is already a local class mean. Its support
    count is existing scalar metadata used by reliability; no feature tensor is
    added to the communication payload. Missing/zero support falls back to one.
    """
    weighted_sum = None
    total = 0.0
    for source_id, outputs in input_outputs.items():
        if outputs is None:
            continue
        prototypes, _ = outputs
        for class_id, prototype in prototypes.items():
            count = 1
            if support_map is not None:
                count = int(support_map.get(source_id, {}).get(class_id, 0)) or 1
            target_device = torch.device(device) if device is not None else prototype.device
            term = prototype.detach().to(target_device) * count
            weighted_sum = term.clone() if weighted_sum is None else weighted_sum + term
            total += count
    if weighted_sum is None:
        raise ValueError("cannot derive a global feature mean from empty prototype stats")
    return weighted_sum / total


def center_features(features: torch.Tensor, mean: Optional[torch.Tensor]) -> torch.Tensor:
    """Subtract a boundary mean from batched real or synthetic features."""
    if mean is None:
        return features
    return features - mean.to(device=features.device, dtype=features.dtype).unsqueeze(0)


def center_source_outputs(input_outputs: Mapping, mean: torch.Tensor) -> Dict:
    """Return prototype dictionaries expressed in the centered space."""
    centered = {}
    for source_id, outputs in input_outputs.items():
        if outputs is None:
            centered[source_id] = None
            continue
        prototypes, stds = outputs
        centered[source_id] = (
            {
                class_id: prototype - mean.to(prototype.device, prototype.dtype)
                for class_id, prototype in prototypes.items()
            },
            stds,
        )
    return centered


@torch.no_grad()
def recenter_memory(memory, old_mean: Optional[torch.Tensor], new_mean: torch.Tensor) -> None:
    """Move historical centered records into a newly selected centered frame."""
    if memory is None or old_mean is None:
        return
    shift = old_mean.detach().cpu() - new_mean.detach().cpu()
    for record in memory.get_recent():
        record.mu = record.mu + shift.to(record.mu.dtype)


class CosineClassifier(nn.Module):
    """Angular classifier: ``logits = scale * cosine(weight, feature)``."""

    def __init__(self, in_features: int, num_classes: int, initial_scale: float = 16.0):
        super().__init__()
        self.in_features = int(in_features)
        self.num_classes = int(num_classes)
        self.weight = nn.Parameter(torch.empty(num_classes, in_features))
        self.scale = nn.Parameter(torch.tensor(float(initial_scale)))
        nn.init.xavier_uniform_(self.weight)

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        features = features.reshape(features.shape[0], -1)
        return self.scale * F.linear(
            F.normalize(features, dim=1), F.normalize(self.weight, dim=1)
        )

"""Pure research metrics used by E-HSFP experiment reporting.

The operational definitions are frozen in ``docs/JOURNAL_SIMULATION_RESULTS.md``
(section 3.9).  This module deliberately contains no training-loop state or
checkpoint-selection logic.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import TypeVar

import torch

from camera_ready.feature_distance import rbf_mmd


ClassId = TypeVar("ClassId")


def trailing_window_stability(
    metric_history: Sequence[float], window: int = 5
) -> list[float | None]:
    """Return trailing population variance, with ``None`` until W observations."""
    if window <= 0:
        raise ValueError("window must be positive")

    stability: list[float | None] = []
    for end in range(1, len(metric_history) + 1):
        if end < window:
            stability.append(None)
            continue
        values = [float(value) for value in metric_history[end - window : end]]
        mean = sum(values) / window
        stability.append(sum((value - mean) ** 2 for value in values) / window)
    return stability


def rounds_to_convergence(
    metric_history: Sequence[float],
    smoothing_window: int = 3,
    threshold_fraction: float = 0.95,
    patience: int = 3,
) -> int | str:
    """Return the first 1-based round sustaining the frozen convergence rule.

    A trailing moving average is defined only once its full smoothing window is
    available.  The threshold is ``threshold_fraction`` times the best raw
    validation metric observed in the run.  A candidate must remain at or above
    that threshold for ``patience`` consecutive smoothed observations.
    """
    if smoothing_window <= 0:
        raise ValueError("smoothing_window must be positive")
    if patience <= 0:
        raise ValueError("patience must be positive")
    if not 0.0 <= threshold_fraction <= 1.0:
        raise ValueError("threshold_fraction must be between 0 and 1")
    if not metric_history:
        return "not_converged"

    values = [float(value) for value in metric_history]
    threshold = threshold_fraction * max(values)
    smoothed: list[tuple[int, float]] = []
    for end in range(smoothing_window, len(values) + 1):
        average = sum(values[end - smoothing_window : end]) / smoothing_window
        smoothed.append((end, average))  # end is also the original 1-based round

    for candidate in range(len(smoothed)):
        patience_window = smoothed[candidate : candidate + patience]
        if len(patience_window) < patience:
            break
        if all(average >= threshold for _, average in patience_window):
            return smoothed[candidate][0]
    return "not_converged"


def prototype_drift(
    prev_prototypes: Mapping[ClassId, torch.Tensor] | None,
    curr_prototypes: Mapping[ClassId, torch.Tensor],
) -> dict[ClassId | str, float] | None:
    """Return per-class L2 drift plus global mean and maximum summaries.

    Only classes present in both rounds can be compared.  ``None`` is the
    explicit no-previous-round sentinel; it prevents round 1 being mislabeled
    as zero drift.  If rounds share no classes, the result is also undefined.
    """
    if not prev_prototypes:
        return None

    shared_classes = prev_prototypes.keys() & curr_prototypes.keys()
    if not shared_classes:
        return None

    per_class = {
        class_id: float(
            torch.linalg.vector_norm(
                curr_prototypes[class_id].detach() - prev_prototypes[class_id].detach()
            ).item()
        )
        for class_id in shared_classes
    }
    distances = list(per_class.values())
    return {
        **per_class,
        "global": sum(distances) / len(distances),
        "max": max(distances),
    }


def recovery_gap(clean_final_metric: float, stressed_final_metric: float) -> float:
    """Return clean minus stressed best-validation-checkpoint metric."""
    return float(clean_final_metric) - float(stressed_final_metric)


def recovery_rounds(
    post_stress_metric_history: Sequence[float],
    pre_stress_metric: float,
    threshold_fraction: float = 0.95,
) -> int | None:
    """Return the first 1-based post-lift round reaching 95% of pre-stress."""
    if not 0.0 <= threshold_fraction <= 1.0:
        raise ValueError("threshold_fraction must be between 0 and 1")
    threshold = threshold_fraction * float(pre_stress_metric)
    return next(
        (round_index for round_index, value in enumerate(post_stress_metric_history, 1)
         if float(value) >= threshold),
        None,
    )


def prototype_fidelity_mmd(
    real_class_features: torch.Tensor,
    synthetic_class_features: torch.Tensor,
    *,
    sigmas=None,
    max_samples: int = 2000,
) -> float:
    """Compute fidelity for matched class/round feature tensors using RBF MMD².

    Callers are responsible for supplying real client-encoder features and the
    corresponding synthetic prototype-space samples for the same class/round.
    """
    if real_class_features.shape[0] == 0 or synthetic_class_features.shape[0] == 0:
        raise ValueError("real and synthetic feature tensors must be non-empty")
    return rbf_mmd(
        real_class_features,
        synthetic_class_features,
        sigmas=sigmas,
        max_samples=max_samples,
    )
